def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    me = [h[0] for h in history]
    opp = [h[1] for h in history]

    opp_c = sum(1 for o in opp if o == 'C')
    if n >= 2 and opp_c == 0:
        return 'D'

    first_my_d = n
    for i, a in enumerate(me):
        if a == 'D':
            first_my_d = i
            break

    opp_d_before = 0
    for i in range(first_my_d):
        if opp[i] == 'D':
            opp_d_before += 1

    exploit = opp_d_before >= 2

    if exploit:
        if first_my_d == n:
            return 'D'
        if opp_c * 5 < n:
            return 'D'
        if n % 5 == 4:
            return 'D'
        return 'C'
    else:
        if n == 99:
            return 'D'
        return 'C'
